-- PostgreSQL18 空库基线：应用模型与 V74 最终结构；不重跑历史数据回填。
-- 上线导入前还必须核对源库独有表/列/索引，并单独处理历史遗留数据。
create table admin_users (created_at timestamp(6) with time zone, last_login_at timestamp(6) with time zone, updated_at timestamp(6) with time zone, display_name varchar(255), email varchar(255), id varchar(255) not null, password_hash varchar(255), role varchar(255) check (role in ('SUPER_ADMIN','OPERATOR','FINANCE_ADMIN')), status varchar(255) check (status in ('ACTIVE','SUSPENDED')), username varchar(255) not null unique, primary key (id));
create table aep_advertisements (duration integer not null, payment bigint not null, views bigint not null, brand varchar(255) not null, id varchar(255) not null, product varchar(255), status varchar(255) check (status in ('NEGOTIATING','SHOOTING','COMPLETED')), type varchar(255) check (type in ('TVC','DIGITAL','PRINT','SOCIAL')), primary key (id));
create table aep_albums (track_count integer not null, created_at timestamp(6) with time zone, revenue bigint not null, sales bigint not null, artist_id varchar(36), cover varchar(512), id varchar(255) not null, name varchar(255) not null, status varchar(255) check (status in ('PLANNING','RECORDING','RELEASED')), track_ids text, primary key (id));
create table aep_audit_logs (created_at timestamp(6) with time zone, result varchar(16) check (result in ('SUCCESS','FAILURE')), app_code varchar(32), action varchar(64), error_code varchar(64), ip_address varchar(64), resource_type varchar(64), tenant_id varchar(64), user_id varchar(64), resource_id varchar(128), username varchar(128), user_agent varchar(512), id varchar(255) not null, detail text, primary key (id));
create table aep_community_events (event_date date, participants integer not null, id varchar(255) not null, status varchar(255) not null check (status in ('LIVE','UPCOMING','ENDED')), title varchar(255) not null, type varchar(255) not null check (type in ('MEETUP','VOTE','CHALLENGE','ANNIVERSARY')), primary key (id));
create table aep_community_posts (created_at timestamp(6) with time zone, artist_id varchar(255), id varchar(255) not null, user_id varchar(255) not null, content text, media_urls text, primary key (id));
create table aep_concerts (capacity integer not null, sold_tickets integer not null, date timestamp(6) with time zone, revenue bigint not null, ticket_price bigint not null, stream_url varchar(512), id varchar(255) not null, name varchar(255) not null, status varchar(255) check (status in ('PLANNING','SELLING','COMPLETED')), venue varchar(255), artist_ids text, primary key (id));
create table aep_copyrights (submitted_date date, artist_name varchar(255), content_type varchar(255), id varchar(255) not null, status varchar(255) not null check (status in ('PENDING','VERIFIED')), submitted_by_user_id varchar(255), title varchar(255) not null, primary key (id));
create table aep_credit_campaigns (active boolean not null, max_concurrent_per_wallet integer not null, per_wallet_daily_resource_limit numeric(25,9) not null, resource_limit numeric(25,9) not null, resource_reserved numeric(25,9) not null, resource_used numeric(25,9) not null, expires_at timestamp(6) with time zone, issued bigint not null, per_wallet_issue_limit bigint not null, starts_at timestamp(6) with time zone, total_issue_limit bigint not null, updated_at timestamp(6) with time zone, version bigint not null, resource_unit varchar(16) not null, id varchar(64) not null, updated_by varchar(64), name varchar(128) not null, targets_json TEXT not null, primary key (id));
create table aep_credit_grant_holds (allocation_order integer not null, consumed bigint not null, frozen bigint not null, original_amount bigint not null, released bigint not null, grant_id varchar(64) not null, hold_id varchar(64) not null, id varchar(64) not null, primary key (id), constraint uk_scoped_grant_hold unique (hold_id, grant_id));
create table aep_credit_grants (amount bigint not null, available bigint not null, created_at timestamp(6) with time zone, expired bigint not null, expires_at timestamp(6) with time zone, frozen bigint not null, spent bigint not null, campaign_id varchar(64) not null, created_by varchar(64) not null, id varchar(64) not null, source varchar(64) not null, wallet_id varchar(64) not null, source_reference varchar(128) not null, reason varchar(512) not null, primary key (id), constraint uk_scoped_grant_source unique (source, source_reference));
create table aep_credit_holds (amount bigint not null, completed_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, from_gift bigint not null, from_license bigint not null, from_recharge bigint not null, remaining_amount bigint not null, updated_at timestamp(6) with time zone not null, status varchar(16) not null check (status in ('ACTIVE','COMMITTED','RELEASED')), actor_user_id varchar(64), enterprise_id varchar(64), id varchar(64) not null, membership_id varchar(64), reference_type varchar(64) not null, user_id varchar(64), wallet_id varchar(64) not null, billing_authorization_id varchar(128), reference_id varchar(128) not null, description varchar(256), primary key (id), constraint uk_credit_hold_ref unique (reference_type, reference_id));
create table aep_credit_packs (recommended boolean, credits bigint not null, price_cents bigint not null, code varchar(255) not null check (code in ('STARTER','STANDARD','PRO','ENTERPRISE')), id varchar(255) not null, name varchar(255) not null, status varchar(255) not null check (status in ('ACTIVE','ARCHIVED')), highlights text, primary key (id));
create table aep_credit_purchases (created_at timestamp(6) with time zone, credits_added bigint not null, price_cents bigint not null, id varchar(255) not null, pack_id varchar(255) not null, user_id varchar(255) not null, payment_meta_json text, primary key (id));
create table aep_credit_resource_reservations (original_units numeric(25,9) not null, released numeric(25,9) not null, reserved numeric(25,9) not null, used numeric(25,9) not null, completed_at timestamp(6) with time zone, created_at timestamp(6) with time zone, dispatched_at timestamp(6) with time zone, campaign_id varchar(64) not null, hold_id varchar(64) not null, id varchar(64) not null, wallet_id varchar(64) not null, primary key (id), constraint uk_scoped_resource_hold unique (hold_id, campaign_id));
create table aep_distribution_contents (platform_count integer not null, publish_date date, total_views_count bigint not null, content_type varchar(255), id varchar(255) not null, status varchar(255) not null check (status in ('PUBLISHED','DISTRIBUTING','SCHEDULED','DRAFT')), title varchar(255) not null, primary key (id));
create table aep_distribution_queue (platform_count integer not null, submit_date date, artist_name varchar(255), id varchar(255) not null, status varchar(255) not null check (status in ('REVIEWING','APPROVED','DISTRIBUTING')), title varchar(255) not null, type varchar(255) not null check (type in ('MUSIC','VIDEO','LIVE')), primary key (id));
create table aep_dramas (episodes integer not null, rating float(53) not null, release_date timestamp(6) with time zone, revenue bigint not null, views bigint not null, genre varchar(255), id varchar(255) not null, role varchar(255), status varchar(255) check (status in ('CASTING','FILMING','POST_PRODUCTION','RELEASED')), title varchar(255) not null, primary key (id));
create table aep_enterprise_audit (created_at timestamp(6) with time zone not null, action varchar(64) not null, actor_user_id varchar(64) not null, enterprise_id varchar(64) not null, id varchar(64) not null, target_id varchar(64) not null, summary text not null, primary key (id));
create table aep_enterprise_billing_authorizations (amount bigint not null, created_at timestamp(6) with time zone not null, dispatched_at timestamp(6) with time zone, revoked_at timestamp(6) with time zone, terminal_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, status varchar(24) not null, actor_user_id varchar(64) not null, endpoint_id varchar(64), enterprise_id varchar(64) not null, id varchar(64) not null, membership_id varchar(64) not null, reference_type varchar(64) not null, wallet_id varchar(64) not null, reference_id varchar(128) not null, primary key (id), constraint uk_enterprise_billing_ref unique (reference_type, reference_id));
create table aep_enterprise_cash_receipts (created_at timestamp(6) with time zone not null, direction varchar(16) not null, order_id varchar(64) not null, id varchar(72) not null, receipt_reference varchar(256) not null, primary key (id));
create table aep_enterprise_credit_lot_holds (frozen bigint not null, original_amount bigint not null, released_amount bigint not null, hold_id varchar(64) not null, id varchar(64) not null, lot_id varchar(64) not null, primary key (id), constraint uk_enterprise_lot_hold unique (hold_id, lot_id));
create table aep_enterprise_credit_lots (available bigint not null, created_at timestamp(6) with time zone not null, frozen bigint not null, enterprise_id varchar(64) not null, id varchar(64) not null, recharge_order_id varchar(64) not null, wallet_id varchar(64) not null, primary key (id), constraint uk_enterprise_credit_lot unique (recharge_order_id, wallet_id));
create table aep_enterprise_current (enterprise_id varchar(64) not null, member_id varchar(64) not null unique, user_id varchar(64) not null, primary key (user_id));
create table aep_enterprise_invitations (created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, status varchar(16) not null, client_request_id varchar(64) not null, created_by varchar(64) not null, enterprise_id varchar(64) not null, id varchar(64) not null, token_hash varchar(64) not null unique, primary key (id), constraint uk_enterprise_invite_request unique (enterprise_id, created_by, client_request_id));
create table aep_enterprise_lifecycle_operations (created_at timestamp(6) with time zone not null, actor_user_id varchar(64) not null, client_request_id varchar(64) not null, enterprise_id varchar(64) not null, fingerprint varchar(64) not null, id varchar(64) not null, result_json text not null, primary key (id), constraint uk_enterprise_lifecycle_request unique (enterprise_id, client_request_id));
create table aep_enterprise_members (billing_read boolean not null, points_manage boolean not null, recharge_request boolean not null, joined_at timestamp(6) with time zone not null, version bigint not null, billing_default varchar(16), role varchar(16) not null, status varchar(16) not null, enterprise_id varchar(64) not null, id varchar(64) not null, user_id varchar(64) not null, primary key (id));
create table aep_enterprise_ownership_transfers (expires_at timestamp(6) with time zone not null, from_owner_version bigint not null, status varchar(16) not null, client_request_id varchar(64) not null, enterprise_id varchar(64) not null, from_user_id varchar(64) not null, id varchar(64) not null, to_user_id varchar(64) not null, primary key (id), constraint uk_enterprise_transfer_request unique (enterprise_id, from_user_id, client_request_id));
create table aep_enterprise_points_batches (created_at timestamp(6) with time zone not null, total_amount bigint not null, direction varchar(16) not null, actor_user_id varchar(64) not null, client_request_id varchar(64) not null, enterprise_id varchar(64) not null, fingerprint varchar(64) not null, id varchar(64) not null, primary key (id), constraint uk_enterprise_batch_request unique (enterprise_id, client_request_id));
create table aep_enterprise_points_transfers (amount bigint not null, from_gift bigint not null, from_license bigint not null, from_recharge bigint not null, batch_id varchar(64) not null, from_wallet_id varchar(64) not null, id varchar(64) not null, in_ledger_id varchar(64) not null, member_id varchar(64) not null, out_ledger_id varchar(64) not null, to_wallet_id varchar(64) not null, primary key (id));
create table aep_enterprise_policies (max_active_jobs integer not null, version bigint not null, enterprise_id varchar(64) not null, allowed_endpoint_ids_json text not null, primary key (enterprise_id));
create table aep_enterprises (created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, version bigint not null, status varchar(16) not null, create_request_id varchar(64) not null, created_by varchar(64) not null, id varchar(64) not null, owner_user_id varchar(64) not null, name varchar(128) not null, primary key (id), constraint uk_enterprise_create unique (created_by, create_request_id));
create table aep_error_logs (http_status integer, occurred_at timestamp(6) with time zone not null, http_method varchar(16), log_id varchar(32) not null unique, client_ip varchar(64), error_code varchar(64), trace_id varchar(64), user_id varchar(64), error_type varchar(128), hostname varchar(128), username varchar(128), endpoint varchar(512), user_agent varchar(512), id varchar(255) not null, message text, request_params text, stacktrace text, primary key (id));
create table aep_event_rsvps (created_at timestamp(6) with time zone, event_id varchar(255) not null, user_id varchar(255) not null, primary key (event_id, user_id));
create table aep_fan_activities (created_at timestamp(6) with time zone, action varchar(255) not null, avatar varchar(255), id varchar(255) not null, type varchar(255) not null check (type in ('COMMENT','GIFT','SHARE','FOLLOW')), user_name varchar(255) not null, primary key (id));
create table aep_fan_growth (active bigint not null, fans bigint not null, date_label varchar(255) not null, id varchar(255) not null, primary key (id));
create table aep_fan_tiers (count integer not null, bg varchar(255), color varchar(255), icon varchar(255), id varchar(255) not null, name varchar(255) not null, primary key (id));
create table aep_forge_blueprints (created_at timestamp(6) with time zone, artist_id varchar(255) not null, id varchar(255) not null, result_id varchar(255) not null, snapshot_json text, primary key (id));
create table aep_forge_results (created_at timestamp(6) with time zone, artist_id varchar(255), id varchar(255) not null, image varchar(255), mode varchar(255) not null check (mode in ('TEMPLATE_PHOTO','PROMPT_ONLY','TEMPLATE_PROMPT','RANDOM')), video_url varchar(255), locked text, prompt text, primary key (id));
create table aep_forge_templates (id varchar(255) not null, image varchar(255), name varchar(255) not null, style varchar(255), tags text, primary key (id));
create table aep_ledger_entries (amount bigint not null, balance_after bigint not null, created_at timestamp(6) with time zone, actor_user_id varchar(64), enterprise_id varchar(64), grant_id varchar(64), membership_id varchar(64), billing_authorization_id varchar(128), cash_artifact_id varchar(255), description varchar(255), entry_type varchar(255) check (entry_type in ('LICENSE_GRANT','RECHARGE','REFUND','REFUND_CASH','INCOME','GIFT','SPEND','WITHDRAW','FREEZE','UNFREEZE','ADJUST','TRANSFER_IN','TRANSFER_OUT','SCOPED_GRANT','SCOPED_FREEZE','SCOPED_SPEND','SCOPED_RELEASE','SCOPED_EXPIRE')), id varchar(255) not null, plane varchar(255) check (plane in ('MONEY','CREDIT')), reference_id varchar(255), reference_type varchar(255), user_id varchar(255), wallet_id varchar(255), primary key (id), check (plane <> 'CREDIT' OR cash_artifact_id IS NULL));
create table aep_license_batches (activated_count integer not null, total_count integer not null, created_at timestamp(6) with time zone, initial_credit_grant bigint not null, valid_from timestamp(6) with time zone, valid_to timestamp(6) with time zone, tier varchar(32), selling_channel_id varchar(64), platforms varchar(128), batch_no varchar(255) not null unique, id varchar(255) not null, issuer_tenant_id varchar(255), name varchar(255) not null, status varchar(255) check (status in ('ACTIVE','EXHAUSTED','REVOKED','EXPIRED')), primary key (id));
create table aep_license_keys (activated_at timestamp(6) with time zone, created_at timestamp(6) with time zone, expires_at timestamp(6) with time zone, activated_by_user_id varchar(255), batch_id varchar(255), code_hash varchar(255) not null unique, id varchar(255) not null, masked_code varchar(255), status varchar(255) check (status in ('CREATED','ACTIVATED','EXPIRED','REVOKED')), primary key (id));
create table aep_memberships (joined_at timestamp(6) with time zone, id varchar(255) not null, license_key_id varchar(255), source varchar(255) check (source in ('LICENSE_ACTIVATION','SELF_REGISTER','ADMIN_INVITE')), tenant_id varchar(255), user_id varchar(255), primary key (id));
create table aep_model_charges (free_only boolean not null, settled_output_quantity numeric(25,9) not null, settled_quantity numeric(25,9) not null, base_credits bigint not null, created_at timestamp(6) with time zone, payable_credits bigint not null, scoped_credits bigint not null, settled_base_credits bigint not null, settled_payable_credits bigint not null, settled_scoped_credits bigint not null, settled_wallet_credits bigint not null, standard_credits bigint not null, wallet_credits bigint not null, hold_id varchar(64) not null, parent_hold_id varchar(64), snapshot_json TEXT not null, target_json TEXT not null, primary key (hold_id));
create table aep_model_discounts (active boolean not null, allow_grants boolean not null, factor numeric(10,6) not null, expires_at timestamp(6) with time zone, starts_at timestamp(6) with time zone, updated_at timestamp(6) with time zone, version bigint not null, audience varchar(16) not null, audience_id varchar(64), id varchar(64) not null, target_key varchar(64) not null, updated_by varchar(64), name varchar(128) not null, target_json TEXT not null, primary key (id));
create table aep_model_prices (active boolean not null, output_unit_price numeric(25,9), unit_price numeric(25,9) not null, updated_at timestamp(6) with time zone, version bigint not null, id varchar(64) not null, target_key varchar(64) not null unique, updated_by varchar(64), name varchar(128) not null, target_json TEXT not null, primary key (id));
create table aep_movies (rating float(53) not null, box_office bigint not null, revenue bigint not null, genre varchar(255), id varchar(255) not null, role varchar(255) check (role in ('LEAD','SUPPORTING','CAMEO')), status varchar(255) check (status in ('PRE_PRODUCTION','FILMING','POST_PRODUCTION','RELEASED')), title varchar(255) not null, primary key (id));
create table aep_music_genres (color varchar(255), icon varchar(255), id varchar(255) not null, name varchar(255) not null, primary key (id));
create table aep_notifications (created_at timestamp(6) with time zone, viewed_at timestamp(6) with time zone, audience_scope varchar(16), audience_target_id varchar(64), audience_target_name varchar(128), bot_id varchar(255), id varchar(255) not null, title varchar(255) not null, type varchar(255) not null check (type in ('REVENUE','FAN','CONTENT','SYSTEM','ACHIEVEMENT')), user_id varchar(255) not null, description text, primary key (id));
create table aep_payment_channels (enabled boolean not null, sandbox boolean not null, sort_order integer not null, version integer not null, updated_at timestamp(6) with time zone, code varchar(32) not null, default_way_code varchar(32), label varchar(64), updated_by varchar(64), creds_encrypted text, primary key (code));
create table aep_platform_configs (version integer not null, updated_at timestamp(6) with time zone, updated_by varchar(64), config_key varchar(128) not null unique, description varchar(512), id varchar(255) not null, value_json text, primary key (id));
create table aep_platform_connections (connected_at timestamp(6) with time zone, id varchar(255) not null, platform_id varchar(255) not null, status varchar(255) not null check (status in ('PENDING','CONNECTED','FAILED','DISCONNECTED')), tenant_id varchar(255) not null, user_id varchar(255) not null, credentials_json text, primary key (id));
create table aep_platforms (followers_count bigint not null, last_sync_at timestamp(6) with time zone, category varchar(255) not null check (category in ('MUSIC','VIDEO','SOCIAL','LIVE')), icon varchar(255), id varchar(255) not null, name varchar(255) not null, status varchar(255) not null check (status in ('CONNECTED','PENDING','DISCONNECTED')), primary key (id));
create table aep_publish_job_events (progress integer, at timestamp(6) with time zone not null, kind varchar(32) not null, from_status varchar(32) check (from_status in ('QUEUED','UPLOADING','TRANSCODING','PUBLISHING','LIVE','AWAITING_USER','FAILED','CANCELLED')), id varchar(255) not null, job_id varchar(255) not null, to_status varchar(32) check (to_status in ('QUEUED','UPLOADING','TRANSCODING','PUBLISHING','LIVE','AWAITING_USER','FAILED','CANCELLED')), note text, primary key (id));
create table aep_publish_jobs (progress integer not null, retry_count integer not null, created_at timestamp(6) with time zone not null, credits_spent bigint, scheduled_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, error_code varchar(64), external_task_id varchar(128), platform_name varchar(128), product_title varchar(256), title varchar(512), cover_url varchar(1024), external_url varchar(1024), product_link varchar(1024), video_url varchar(1024), id varchar(255) not null, platform varchar(255) not null check (platform in ('DOUYIN','KUAISHOU','XIAOHONGSHU','SHIPINHAO','BILIBILI','TIKTOK','YOUTUBE','BAIJIAHAO')), platform_id varchar(255), project_id varchar(255) not null, social_account_id varchar(255) not null, status varchar(32) not null check (status in ('QUEUED','UPLOADING','TRANSCODING','PUBLISHING','LIVE','AWAITING_USER','FAILED','CANCELLED')), user_id varchar(255) not null, description text, error_message text, interaction_required text, tags text, primary key (id), constraint idx_publish_external_task unique (external_task_id));
create table aep_recharge_records (record_date date, credits_added bigint not null, price_cents bigint not null, id varchar(255) not null, source varchar(255) not null check (source in ('CREDIT_PACK','LICENSE_REDEEM','PROMO_GIFT')), user_id varchar(255), description text, primary key (id));
create table aep_saved_outfits (created_at timestamp(6) with time zone, id varchar(255) not null, name varchar(255) not null, user_id varchar(255) not null, slots_json text, primary key (id));
create table aep_selling_channels (created_at timestamp(6) with time zone, updated_at timestamp(6) with time zone, status varchar(16) not null check (status in ('ACTIVE','INACTIVE')), type varchar(32) not null check (type in ('DIRECT','AGENT','ONLINE_STORE','EVENT','PARTNER')), code varchar(64) not null unique, contact_phone varchar(64), id varchar(64) not null, contact_email varchar(200), name varchar(200) not null, selling_entity varchar(200), remark text, primary key (id));
create table aep_signed_artists (content_count integer not null, contract_end date, royalty_rate integer not null, fans_count bigint not null, monthly_revenue_credits bigint not null, total_revenue_credits bigint not null, artist_type varchar(255), avatar varchar(255), id varchar(255) not null, mcn varchar(255), name varchar(255) not null, status varchar(255) not null check (status in ('ACTIVE','NEGOTIATING','EXPIRING')), type_icon varchar(255), primary key (id));
create table aep_social_accounts (bound_at timestamp(6) with time zone not null, created_at timestamp(6) with time zone not null, last_verified_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, account_name varchar(128) not null, display_name varchar(128), platform_account_id varchar(128), avatar_url varchar(1024), id varchar(255) not null, platform varchar(255) not null check (platform in ('DOUYIN','KUAISHOU','XIAOHONGSHU','SHIPINHAO','BILIBILI','TIKTOK','YOUTUBE','BAIJIAHAO')), status varchar(255) not null check (status in ('PENDING','ACTIVE','EXPIRED','BANNED')), user_id varchar(255) not null, storage_state_encrypted text, primary key (id), constraint uk_social_user_platform_name unique (user_id, platform, account_name));
create table aep_songs (duration integer not null, rating float(53) not null, created_at timestamp(6) with time zone, credits_spent bigint, plays bigint not null, release_date timestamp(6) with time zone, revenue bigint not null, think_depth varchar(16), artist_id varchar(36), owner_user_id varchar(36), model_version varchar(64), audio_cdn_key varchar(512), audio_url varchar(512), cover_url varchar(512), genre varchar(255), id varchar(255) not null, status varchar(255) check (status in ('RECORDING','MIXING','RELEASED')), title varchar(255) not null, lyrics text, primary key (id));
create table aep_studios (created_at timestamp(6) with time zone, updated_at timestamp(6) with time zone, contact_email varchar(255), contact_phone varchar(255), id varchar(255) not null, kind varchar(255) not null check (kind in ('PERSONAL_CREATOR','MUSIC_STUDIO','DRAMA_STUDIO','VARIETY_STUDIO','AGENCY','MCN')), logo_url varchar(255), name varchar(255) not null, owner_user_id varchar(255) not null unique, status varchar(255) not null check (status in ('ACTIVE','SUSPENDED','DELETED')), bio text, primary key (id));
create table aep_tenants (created_at timestamp(6) with time zone, updated_at timestamp(6) with time zone, id varchar(255) not null, kind varchar(255) check (kind in ('PLATFORM','PERSONAL','ORGANIZATION')), name varchar(255) not null, status varchar(255) check (status in ('ACTIVE','SUSPENDED','DELETED')), primary key (id));
create table aep_user_inventory (credits_spent integer not null, acquired_at timestamp(6) with time zone, source varchar(16) not null check (source in ('PURCHASE','GRANT','DEFAULT')), item_type varchar(32) not null check (item_type in ('WARDROBE','POSE','EXPRESSION','GESTURE','NFT','FORGE_BLUEPRINT')), item_id varchar(64) not null, ledger_entry_id varchar(64), user_id varchar(64) not null, id varchar(255) not null, primary key (id), constraint ux_inv_user_item unique (user_id, item_type, item_id));
create table aep_users (email_verified boolean not null, phone_verified boolean not null, created_at timestamp(6) with time zone, identity_state_event_id bigint, identity_tokens_valid_after timestamp(6) with time zone, last_login_at timestamp(6) with time zone, updated_at timestamp(6) with time zone, identity_state varchar(20), identity_uid varchar(32) unique, operator_role varchar(32) check (operator_role in ('OPERATOR','SUPER_ADMIN')), platforms varchar(128), bio varchar(1024), avatar_url varchar(255), display_name varchar(255), email varchar(255), id varchar(255) not null, kind varchar(255) check (kind in ('PERSONAL','STUDIO')), lang_preference varchar(255), password_hash varchar(255), phone varchar(255), status varchar(255) check (status in ('ACTIVE','SUSPENDED','DELETED')), username varchar(255) not null unique, wallet_address varchar(255), primary key (id));
create table aep_voice_works (duration integer not null, payment bigint not null, id varchar(255) not null, project varchar(255) not null, status varchar(255) check (status in ('RECORDING','EDITING','DELIVERED')), type varchar(255) check (type in ('ANIMATION','DOCUMENTARY','AUDIOBOOK','GAME')), primary key (id));
