create table star_ai_likeness_requests (requested_at timestamp(6) with time zone not null, risk_level varchar(16) not null check (risk_level in ('LOW','MEDIUM','HIGH')), model_type varchar(32) not null check (model_type in ('VOICE','FACE','FULL_BODY')), status varchar(32) not null check (status in ('PENDING','APPROVED','REJECTED')), purpose varchar(512) not null, ai_vendor varchar(255) not null, id varchar(255) not null, mcn_name varchar(255) not null, star_id varchar(255) not null, platforms_json text, primary key (id));
