create table star_content_reviews (duration_sec integer not null, submitted_at timestamp(6) with time zone not null, views bigint, platform varchar(32) not null, status varchar(32) not null check (status in ('PENDING','APPROVED','REVISION','REJECTED')), type varchar(32) not null check (type in ('CLIP','DIGITAL_HUMAN','AI_LIKENESS')), title varchar(256) not null, revision_note varchar(512), id varchar(255) not null, mcn_name varchar(255) not null, star_id varchar(255) not null, uploader varchar(255) not null, primary key (id));
create table star_content_rules (enabled boolean not null, sort_order integer not null, zone varchar(16) not null check (zone in ('GREEN','YELLOW','ORANGE','RED')), name varchar(128) not null, description varchar(512) not null, id varchar(255) not null, star_id varchar(255) not null, primary key (id));
create table star_contracts (end_date date not null, sign_date date not null, start_date date not null, amount_cents bigint not null, status varchar(32) not null check (status in ('ACTIVE','EXPIRED','PENDING','TERMINATED')), type varchar(32) not null check (type in ('AUTHORIZATION','AMENDMENT','SETTLEMENT')), ip_name varchar(128) not null, title varchar(256) not null, id varchar(255) not null, mcn_name varchar(255) not null, star_id varchar(255) not null, primary key (id));
create table star_digital_human_requests (duration_months integer not null, requested_at timestamp(6) with time zone not null, status varchar(32) not null check (status in ('PENDING','APPROVED','REJECTED')), usage_type varchar(32) not null check (usage_type in ('LIVE','SHORT_VIDEO','ADS')), purpose varchar(512) not null, risk_note varchar(512), id varchar(255) not null, mcn_name varchar(255) not null, star_id varchar(255) not null, platforms_json text, primary key (id));
create table star_infringement_cases (reported_at timestamp(6) with time zone not null, severity varchar(16) not null check (severity in ('HIGH','MEDIUM','LOW')), status varchar(32) not null check (status in ('PENDING','INVESTIGATING','CONFIRMED','RESOLVED')), platform varchar(64) not null, reported_by varchar(64) not null, ip_name varchar(128) not null, action_note varchar(512), description varchar(1024) not null, url varchar(1024) not null, id varchar(255) not null, star_id varchar(255) not null, primary key (id));
create table star_ip_assets (activated_at date, files_count integer not null, required_files integer not null, uploaded_at date, status varchar(32) not null check (status in ('NOT_STARTED','PREPARING','UPLOADED','TECH_RECEIVED','VOLCANO_SYNC','ACTIVE')), type varchar(32) not null check (type in ('PORTRAIT','CLIP','DIGITAL_HUMAN','DOCUMENTS')), note varchar(512), id varchar(255) not null, star_id varchar(255) not null, tech_company varchar(255) not null, volcano_project_id varchar(255), primary key (id), unique (star_id, type));
create table star_product_onboards (library_at date, price_cents integer not null, sales_count integer not null, step integer not null, submitted_at timestamp(6) with time zone not null, celeb_sample varchar(32) not null check (celeb_sample in ('NOT_SENT','SHIPPING','DELIVERED','APPROVED','REJECTED')), platform_sample varchar(32) not null check (platform_sample in ('NOT_SENT','SHIPPING','DELIVERED','APPROVED','REJECTED')), source varchar(32) not null check (source in ('PLATFORM','CREATOR','BRAND')), category varchar(64) not null, product_name varchar(256) not null, platform_note varchar(512), brand varchar(255) not null, id varchar(255) not null, mcn_name varchar(255), product_id varchar(255), star_id varchar(255) not null, submitted_by varchar(255) not null, submitted_by_user_id varchar(255), tracking_celeb varchar(255), tracking_platform varchar(255), primary key (id));
create table star_revenue_months (share_percent integer not null, amount_cents bigint not null, gmv_cents bigint not null, rev_month varchar(8) not null, status varchar(32) not null check (status in ('PROCESSING','PAID')), id varchar(255) not null, star_id varchar(255) not null, primary key (id), unique (star_id, rev_month));
create table star_whitelist_requests (account_age_months integer not null, credit_score integer not null, recent_videos integer not null, avg_views bigint not null, fans bigint not null, requested_at timestamp(6) with time zone not null, mcn_level varchar(32) not null, platform varchar(32) not null, status varchar(32) not null check (status in ('PENDING','APPROVED','REJECTED','INFO_REQUIRED')), whitelist_step varchar(32) not null check (whitelist_step in ('RECEIVED','CONTACTING','SMS','PROCESSING','AUTHORIZED')), message varchar(512), account_handle varchar(255) not null, account_id varchar(255) not null, id varchar(255) not null, mcn_name varchar(255) not null, phone varchar(255) not null, star_id varchar(255) not null, uid varchar(255) not null, primary key (id));
create table storage_assets (bytes bigint not null, created_at timestamp(6) with time zone, cdn_key varchar(512), app varchar(255), category varchar(255), id varchar(255) not null, owner_user_id varchar(255), ref_id varchar(255), primary key (id));
create table storage_grants (created_at timestamp(6) with time zone, expires_at timestamp(6) with time zone, mb bigint not null, app varchar(255), id varchar(255) not null, owner_user_id varchar(255), source varchar(255), primary key (id));
create table template_scripts (version integer not null, created_at timestamp(6) with time zone not null, published_at timestamp(6) with time zone, id varchar(255) not null, kind varchar(255) not null check (kind in ('TEXT','VIDEO_REF')), language varchar(255) not null, published_by varchar(255), status varchar(255) not null check (status in ('DRAFT','IN_REVIEW','PUBLISHED','ARCHIVED')), template_id varchar(255) not null, duration_variants_json text, engine_adapters_json text, experiment_json text, metrics_json text, negative_prompt text, persona_json text, post_process_json text, reference_clip_json text, safety_json text, scenes_json text, system_prompt text, variables_json text, visual_style_json text, primary key (id), unique (template_id, version));
create table tracks (duration_sec integer not null, plays bigint not null, date varchar(255), duration_label varchar(255), id varchar(255) not null, singer_id varchar(255), status varchar(255), style varchar(255), title_en varchar(255), title_zh varchar(255), primary key (id));
create table user_bot_read_state (last_read_at timestamp(6) with time zone not null, bot_id varchar(255) not null, id varchar(255) not null, user_id varchar(255) not null, primary key (id));
create table video_studio_prompt_optimization (completed_at timestamp(6) with time zone, created_at timestamp(6) with time zone, credits_held bigint not null, updated_at timestamp(6) with time zone, status varchar(16) not null, id varchar(32) not null, endpoint_id varchar(64), owner_user_id varchar(64) not null, client_request_id varchar(128) not null, vendor_optimization_id varchar(128), error_message TEXT, optimized_prompt text, original_prompt text not null, spec_json text not null, primary key (id), constraint uk_vs_opt_owner_request unique (owner_user_id, client_request_id));
create table video_studio_template (use_count integer not null, created_at timestamp(6) with time zone, updated_at timestamp(6) with time zone, scope varchar(16) not null, status varchar(16) not null, id varchar(32) not null, owner_user_id varchar(64) not null, source_job_id varchar(64) not null, title varchar(64) not null, description varchar(400), preview_thumbnail_key varchar(512), preview_video_key varchar(512), recipe_json text not null, primary key (id));
